Method.Source:
Exception add(
    Exception _exception,
    str _txt,
    str _helpUrl,
    Object _sysInfoAction,
    boolean buildprefix,
    str _label)
{
    str txt = _txt;
    TFMTraceLog	traceLog;
    UserConnection	userConnection;

    if (_exception == Exception::Error && TFMTracingUsers::doTrace())
    {
        userConnection = new userConnection();
        userConnection.ttsbegin();
        traceLog.EventMessage = _txt;
        traceLog.CallStack = xSession::xppCallStack();
        traceLog.setConnection(userConnection);
        traceLog.doInsert();
        userConnection.ttscommit();

    }
    return next add(_exception, txt, _helpUrl, _sysInfoAction, buildprefix, _label);
}
